    const descriptor = Object.getOwnPropertyDescriptor(Legacy.prototype, "run")!;
    const out = (traced() as (...args: unknown[]) => PropertyDescriptor)(
      Legacy.prototype,
      "run",
      descriptor,
    );
    Object.defineProperty(Legacy.prototype, "run", out);
    expect(new Legacy().run()).toBe("ran");
    const unbound = traced("free")(
      function free() {
        return 1;
      } as never,
      { kind: "method", name: "free" },
    );
    expect((unbound as unknown as () => number).call(undefined)).toBe(1);
    const names = (await spans()).map((s) => s.name).sort();
    expect(names).toEqual(["Legacy.run", "free"]);
