describe("propagation", () => {
  const traceparent = "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01";

  it("injects and extracts with the global propagator", () => {
    withSpan("outgoing", (span) => {
      const empty: Record<string, string> = {};
      const carrier = inject(empty);
      expect(carrier.traceparent).toContain(span.spanContext().traceId);
      expect(carrier["x-b3-traceid"]).toBe(span.spanContext().traceId);
      const headers = injectHeaders(new Headers());
      expect(headers.get("traceparent")).toContain(span.spanContext().spanId);
      const plainIn: Record<string, string> = {};
      const plain = injectHeaders(plainIn);
      expect(plain.traceparent).toBeDefined();
    });
    const ctx = extract({ TraceParent: traceparent });
    expect(trace.getSpanContext(ctx)?.traceId).toBe("4bf92f3577b34da6a3ce929d0e0e4736");
    const fromHeaders = extractHeaders(new Headers({ traceparent }));
    expect(trace.getSpanContext(fromHeaders)?.spanId).toBe("00f067aa0ba902b7");
    const fromNode = extractHeaders({
      traceparent: [traceparent],
      "content-length": 5,
      missing: undefined,
    });
    expect(trace.getSpanContext(fromNode)?.isRemote).toBe(true);
    expect(trace.getSpanContext(extractHeaders({}))).toBeUndefined();
  });

  it("uses an explicit propagator and context", () => {
    const sc = { traceId: "1".repeat(32), spanId: "2".repeat(16), traceFlags: 1 };
    const ctx = trace.setSpanContext(ROOT_CONTEXT, sc);
    const propagator = handle.propagator;
    const target: Record<string, string> = {};
    const carrier = inject(target, { context: ctx, propagator });
    expect(carrier.traceparent).toBe(`00-${sc.traceId}-${sc.spanId}-01`);
    const headers = injectHeaders(new Headers(), { context: ctx, propagator });
    expect(headers.get("x-b3-spanid")).toBe(sc.spanId);
    expect(
      trace.getSpanContext(extract(carrier, { propagator, context: ROOT_CONTEXT }))?.traceId,
    ).toBe(sc.traceId);
    expect(trace.getSpanContext(extractHeaders(headers, { propagator }))?.traceId).toBe(sc.traceId);
  });
});
